using System;
using System.IO;
using System.Xml;
using PowerPointIntelligence.AddIn;
internal static class XmlPartUpdateTests
{
    internal static void Run()
    {
        int count=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("FAIL XML update "+name);count++;};
        XmlPartUpdates.Validate("<root xmlns='urn:test'><value>1</value></root>");count++;
        foreach(var invalid in new[]{"","<root>","<a/><b/>","<!DOCTYPE a [<!ENTITY e SYSTEM 'file:///never-read'>]><a>&e;</a>",new string('x',1000001)}){bool refused=false;try{XmlPartUpdates.Validate(invalid);}catch(Exception error) when(error is InvalidDataException||error is XmlException){refused=true;}check(refused,"invalid XML refused");}
        check(XmlPartUpdates.RootNamespace("<r xmlns='urn:actual'/>")=="urn:actual","schema identity comes from serialized root rather than stale native namespace");check(XmlPartUpdates.RootNamespace("<r/>")=="","namespace-free XML stays distinct");
        string attached="old";int detached=0,created=0;string replacement=XmlPartUpdates.ReplaceAttachment(()=>{detached++;attached=null;},()=>{check(attached==null,"old attachment is detached before new one is created");created++;attached="new";return "new";},value=>check(attached==value,"final attachment verified"),value=>attached=null,()=>attached="old");check(replacement=="new"&&attached=="new"&&detached==1&&created==1,"replacement commits exactly one new owner attachment");
        attached="old";bool failed=false;try{XmlPartUpdates.ReplaceAttachment<string>(()=>attached=null,()=>{throw new InvalidDataException("create failed");},value=>{},value=>attached=null,()=>attached="old");}catch(InvalidDataException){failed=true;}check(failed&&attached=="old","create failure restores exact prior attachment");
        attached="old";failed=false;try{XmlPartUpdates.ReplaceAttachment(()=>attached=null,()=>{attached="new";return "new";},value=>{throw new InvalidDataException("verification failed");},value=>attached=null,()=>attached="old");}catch(InvalidDataException){failed=true;}check(failed&&attached=="old","post-create verification failure removes replacement and restores prior");
        attached="old";failed=false;try{XmlPartUpdates.ReplaceAttachment<string>(()=>{attached=null;throw new InvalidDataException("partial detach");},()=>"new",value=>{},value=>attached=null,()=>attached="old");}catch(InvalidDataException){failed=true;}check(failed&&attached=="old","partial detach exception still restores prior attachment");
        bool incomplete=false;try{XmlPartUpdates.ReplaceAttachment(()=>{},()=>"new",value=>{throw new InvalidDataException("verify");},value=>{throw new InvalidOperationException("cleanup failed");},()=>{});}catch(InvalidOperationException e){incomplete=e.InnerException is AggregateException;}check(incomplete,"cleanup failure cannot be reported as successful rollback");
        incomplete=false;try{XmlPartUpdates.ReplaceAttachment<string>(()=>{},()=>{throw new InvalidDataException("create");},value=>{},value=>{},()=>{throw new InvalidOperationException("restore failed");});}catch(InvalidOperationException e){incomplete=e.InnerException is AggregateException;}check(incomplete,"restoration failure remains explicit");
        string partId="{AABBCCDD-1122-3344-5566-778899AABBCC}";check(XmlPartUpdates.SamePartId(partId,"aabbccdd112233445566778899aabbcc"),"part GUID comparison ignores spelling/case/braces");check(!XmlPartUpdates.SamePartId(partId,"{AABBCCDD-1122-3344-5566-778899AABBCD}"),"different part identity remains rejected");
        check(XmlPartUpdates.Equivalent("<r xmlns='urn:a' id='1' value='2'><v>label</v></r>","<p:r value='2' xmlns:p='urn:a' id='1'><p:v>label</p:v></p:r>"),"namespace prefixes and attribute order do not change XML data");check(XmlPartUpdates.Equivalent("<r><v>label</v></r>","<r>\n  <v>label</v>\n</r>"),"element-only indentation is representation-only");check(XmlPartUpdates.Equivalent("<r><v><![CDATA[label]]></v></r>","<r><v>label</v></r>"),"CDATA and identical text preserve the same data");
        check(!XmlPartUpdates.Equivalent("<r id='1'/>","<r id='2'/>"),"changed canonical identity attribute rejected");check(!XmlPartUpdates.Equivalent("<r value='1.0'/>","<r value='1.0001'/>"),"numeric field changes are exact, without tolerance");check(!XmlPartUpdates.Equivalent("<r xmlns='urn:a'/>","<r xmlns='urn:b'/>"),"changed schema namespace rejected");check(!XmlPartUpdates.Equivalent("<r><v>A</v><v>B</v></r>","<r><v>B</v><v>A</v></r>"),"ordered children remain ordered");check(!XmlPartUpdates.Equivalent("<r><v> A </v></r>","<r><v>A</v></r>"),"field text whitespace retained");check(!XmlPartUpdates.Equivalent("<r><v> </v></r>","<r><v>  </v></r>"),"whitespace-only field values retained");check(!XmlPartUpdates.Equivalent("<r xml:space='preserve'><v/> </r>","<r xml:space='preserve'><v/>  </r>"),"xml space preservation is honored");check(!XmlPartUpdates.Equivalent("<r><!--A--></r>","<r><!--B--></r>"),"comments are not discarded by structural comparison");
        string deep=String.Concat(System.Linq.Enumerable.Repeat("<n>",140))+String.Concat(System.Linq.Enumerable.Repeat("</n>",140));bool deepRejected=false;try{XmlPartUpdates.Equivalent(deep,deep);}catch(InvalidDataException){deepRejected=true;}check(deepRejected,"XML comparison depth is bounded without recursive stack growth");
        string preservedDeep=deep.Replace("<n>","<n xml:space='preserve'>");deepRejected=false;try{XmlPartUpdates.Equivalent(preservedDeep,preservedDeep);}catch(InvalidDataException){deepRejected=true;}check(deepRejected,"xml space cannot bypass the comparison depth bound");
        var prior=System.Threading.Thread.CurrentThread.CurrentCulture;
        try{System.Threading.Thread.CurrentThread.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("ar-SA");check(LinkedChartData.WorkbookAutomationCulture.LCID==1033,"Excel dispatch LCID remains en-US independent of caller");check(System.Threading.Thread.CurrentThread.CurrentCulture.Name=="ar-SA","Excel culture selection does not change thread culture");}finally{System.Threading.Thread.CurrentThread.CurrentCulture=prior;}
        string canonicalId=Guid.NewGuid().ToString("D"),otherId=Guid.NewGuid().ToString("D");int resolved=0;
        Func<string,string> fresh=id=>{resolved++;return "<r xmlns='urn:canonical'/>";};
        var canonical=XmlPartUpdates.CanonicalParts(new[]{canonicalId,"{"+canonicalId.ToUpperInvariant()+"}"},id=>id,fresh,xml=>xml,"urn:canonical");
        check(canonical.Length==1&&resolved==1,"duplicate native GUID spellings resolve once through owner membership");
        canonical=XmlPartUpdates.CanonicalParts(new[]{canonicalId,otherId},id=>id,fresh,xml=>xml,"urn:canonical");check(canonical.Length==2,"two distinct same-schema parts remain ambiguous even for identical payloads");
        canonical=XmlPartUpdates.CanonicalParts(new[]{canonicalId},id=>id,id=>"<r xmlns='urn:foreign'/>",xml=>xml,"urn:canonical");check(canonical.Length==0,"serialized foreign namespace cannot be mistaken for canonical metadata");
        bool invalidIdentity=false;try{XmlPartUpdates.CanonicalParts(new[]{"bad-id"},id=>id,fresh,xml=>xml,"urn:canonical");}catch(InvalidDataException){invalidIdentity=true;}check(invalidIdentity,"invalid metadata identity rejected before resolution");
        bool missingOwner=false;try{XmlPartUpdates.CanonicalParts(new[]{canonicalId},id=>id,id=>{throw new InvalidDataException("not owned");},xml=>xml,"urn:canonical");}catch(InvalidDataException){missingOwner=true;}check(missingOwner,"lost owner membership is not silently adopted");
        bool excessive=false;try{XmlPartUpdates.CanonicalParts(System.Linq.Enumerable.Repeat(canonicalId,65),id=>id,fresh,xml=>xml,"urn:canonical");}catch(InvalidDataException){excessive=true;}check(excessive,"duplicate IDs cannot bypass metadata enumeration bound");
        int leaseKey=System.Diagnostics.Process.GetCurrentProcess().Id+1000000;bool blocked=false,reacquired=false;Exception workerError=null;
        using(var lease=PowerPointIntelligence.Host.OfficeMutationLease.TryEnter(leaseKey)){
            check(lease!=null,"mutation lease acquired");
            var worker=new System.Threading.Thread(()=>{try{using(var competing=PowerPointIntelligence.Host.OfficeMutationLease.TryEnter(leaseKey)){blocked=competing==null;}}catch(Exception e){workerError=e;}});worker.Start();check(worker.Join(5000),"contending writer returns within bounded time");check(workerError==null&&blocked,"another writer cannot enter the held mutation scope");
            using(var nested=PowerPointIntelligence.Host.OfficeMutationLease.TryEnter(leaseKey))check(nested!=null,"same-thread nested operation remains safe");
        }
        var afterRelease=new System.Threading.Thread(()=>{try{using(var next=PowerPointIntelligence.Host.OfficeMutationLease.TryEnter(leaseKey)){reacquired=next!=null;}}catch(Exception e){workerError=e;}});afterRelease.Start();check(afterRelease.Join(5000)&&workerError==null&&reacquired,"released scope permits the next writer");
        Console.WriteLine(count+" XML update and Excel locale contract assertions passed; native replacement remains an Office acceptance gate.");
    }
}
